from fastapi import status
from fastapi.exceptions import HTTPException


class InvalidProxyMngrCmdArgsException(Exception):

    def __init__(self, message):
        super().__init__(self, message)


class UeproxyPortException(HTTPException):

    def __init__(self, message):
        super().__init__(status_code=status.HTTP_405_METHOD_NOT_ALLOWED, detail=message)


class UeproxyServiceTypeException(Exception):

    def __init__(self, message):
        super().__init__(self, message)
